 LinearLayout root,watch,main,side; TextView priceLabel,status,reason,longPlan,shortPlan,signal,metrics; Chart chart; String symbol="BTCUSDT",interval="5"; double lastPrice=Double.NaN; long updated=0; final ExecutorService pool=Executors.newSingleThreadExecutor(); final Handler handler=new Handler(Looper.getMainLooper()); ArrayList<Candle> candles=new ArrayList<>(); Plan longP,shortP; boolean active=true; String[] symbols={"BTCUSDT","ETHUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","BNBUSDT","ADAUSDT","AVAXUSDT","LINKUSDT","SUIUSDT"};
 static class Candle {double o,h,l,c,v; Candle(JSONArray a) throws Exception {o=Double.parseDouble(a.getString(1));h=Double.parseDouble(a.getString(2));l=Double.parseDouble(a.getString(3));c=Double.parseDouble(a.getString(4));v=Double.parseDouble(a.getString(5));}}
